        const desRoll = clamp(-Math.atan2(bodyAz, totalUp), -maxTilt, maxTilt);

        // Invert inner attitude loop:
        // We want att to track desRoll, desPitch without steady-state offset from intRoll or bRoll.
        // In inner loop: alpha = 65*(cmd - att) - 13*rate + 22*int - 0.4*rate + b
        // Desired alpha: 65*(des - att) - 13*rate
        // So 65*(cmd - att) + 22*int + b = 65*(des - att)  =>  cmd = des - (22*int + b)/65
        let cmdRoll = clamp(desRoll - (22 * intRoll + bRoll) / 65, -0.6, 0.6);
        let cmdPitch = clamp(desPitch - (22 * intPitch + bPitch) / 65, -0.6, 0.6);

        let thrust = totalUp / (kScale * Math.max(0.6, Math.cos(att.roll) * Math.cos(att.pitch)));
        if (phase === 'pad_pin') {
          thrust = 0.05;
          cmdRoll = clamp(cmdRoll, -0.14, 0.14);
          cmdPitch = clamp(cmdPitch, -0.14, 0.14);
        }
        thrust = clamp(thrust, 0, 1);
        const yawRate = clamp(-2.5 * att.yaw, -2, 2);

        // Update inner integral estimates (2 substeps of 0.005)
        intRoll = clamp(intRoll + (cmdRoll - att.roll) * dt, -0.35, 0.35);
        intPitch = clamp(intPitch + (cmdPitch - att.pitch) * dt, -0.35, 0.35);
        lastCmd = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate };

        return lastCmd;
      }
    };
  };
}

