}

function runFast(makeCtrl, seeds) {
  let passed = 0;
  const results = [];
  for (const seed of seeds) {
    const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    const ctrl = makeCtrl();
    for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
      const raw = ctrl.step(observation(state, rng));
      const action = {
        thrust: clamp(raw.thrust, 0, 1), roll: clamp(raw.roll, -0.6, 0.6),
        pitch: clamp(raw.pitch, -0.6, 0.6), yawRate: clamp(raw.yawRate, -2, 2)
      };
      for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
    }
    const success = state.reason === 'landed';
    if (success) passed++;
    results.push({ seed, success, reason: state.reason || 'time limit', gates: state.gateIndex, t: +state.t.toFixed(2) });
  }
  return { passed, total: seeds.length, results };
}

function makeCtrl() {
  let prevRates = null, prevAtt = null, prevVel = null;
  let intRoll = 0, intPitch = 0;
  let bRoll = 0, bPitch = 0;
  let kScale = 16.0 / 0.775;
  let windX = 0, windZ = 0;
  let lastCmd = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };
  let targetIndex = -1, phase = 'align', settle = 0;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (prevRates !== null && obs.t > 0.02) {
        const alphaRoll = (rates.roll - prevRates.roll) / dt;
        const alphaPitch = (rates.pitch - prevRates.pitch) / dt;
        const eRoll = lastCmd.roll - prevAtt.roll;
        const ePitch = lastCmd.pitch - prevAtt.pitch;
        const expAlphaRoll = 65 * eRoll - 13 * prevRates.roll + 22 * intRoll - 0.4 * prevRates.roll;
        const expAlphaPitch = 65 * ePitch - 13 * prevRates.pitch + 22 * intPitch - 0.4 * prevRates.pitch;

        bRoll += 0.08 * ((alphaRoll - expAlphaRoll) - bRoll);
        bPitch += 0.08 * ((alphaPitch - expAlphaPitch) - bPitch);

        const accX = (v.x - prevVel.x) / dt;
        const accY = (v.y - prevVel.y) / dt;
        const accZ = (v.z - prevVel.z) / dt;

        const bodyX = Math.sin(prevAtt.pitch) * Math.cos(prevAtt.roll);
        const bodyZ = -Math.sin(prevAtt.roll);
        const dirX = Math.cos(prevAtt.yaw) * bodyX + Math.sin(prevAtt.yaw) * bodyZ;
        const dirY = Math.cos(prevAtt.pitch) * Math.cos(prevAtt.roll);
        const dirZ = -Math.sin(prevAtt.yaw) * bodyX + Math.cos(prevAtt.yaw) * bodyZ;

        if (p.y > 0.085 && lastCmd.thrust > 0.2) {
          const dragK = 0.42 / 0.775;
          const measK = (accY + 9.81 + dragK * prevVel.y) / (lastCmd.thrust * dirY);
          if (measK > 10 && measK < 32) {
            kScale += 0.08 * (measK - kScale);
          }
        }

        if (p.y > 0.085) {
          const dragK = 0.42 / (15.0 / kScale);
          const dAccX = accX - kScale * lastCmd.thrust * dirX + dragK * prevVel.x;
          const dAccZ = accZ - kScale * lastCmd.thrust * dirZ + dragK * prevVel.z;
          windX += 0.25 * (dAccX - windX);
          windZ += 0.25 * (dAccZ - windZ);
        }
      }

      prevRates = { ...rates };
      prevAtt = { ...att };
      prevVel = { ...v };

      let target;
      let maxTilt = 0.48;
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        if (phase === 'align') {
          const alignX = gate.x - 0.38;
          target = { x: alignX, y: gate.y, z: gate.z };
          const dy = Math.abs(p.y - gate.y);
          const dz = Math.abs(p.z - gate.z);
          const dx = Math.abs(p.x - alignX);
          if (dy < 0.075 && dz < 0.085 && p.x < gate.x - 0.05 && Math.abs(v.y) < 0.45 && Math.abs(v.z) < 0.45 && dx < 0.25) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) phase = 'lunge';
        }
        if (phase === 'lunge') {
          target = { x: gate.x + 0.45, y: gate.y, z: gate.z };
          const dy = Math.abs(p.y + v.y * 0.08 - gate.y);
          const dz = Math.abs(p.z + v.z * 0.08 - gate.z);
          if (p.x < gate.x - 0.12 && (dy > 0.11 || dz > 0.13)) {
            phase = 'align';
            settle = 0;
          }
        }
      } else {
        if (phase !== 'pad_descend' && phase !== 'pad_pin') phase = 'pad_approach';
        const pad = obs.pad.centre;
        const distH = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedH = Math.hypot(v.x, v.z);
        if (phase === 'pad_approach') {
          target = { x: pad.x, y: 0.55, z: pad.z };
          if (distH < 0.18 && speedH < 0.45) phase = 'pad_descend';
        }
        if (phase === 'pad_descend') {
          target = { x: pad.x, y: 0.08, z: pad.z };
          if (distH > 0.28) phase = 'pad_approach';
          if (p.y < 0.11 && distH < 0.13 && speedH < 0.35 && Math.abs(v.y) < 0.35) {
            phase = 'pad_pin';
          }
        }
        if (phase === 'pad_pin') {
          target = { x: pad.x, y: 0.0, z: pad.z };
          maxTilt = 0.14;
          if (distH > 0.145 || p.y > 0.12) phase = 'pad_descend';
        }
      }

      const dragK = 0.42 / (15.0 / kScale);
      let kp = 6.5, kd = 4.2;
      if (phase === 'lunge') { kp = 8.0; kd = 4.5; }
      if (phase === 'pad_descend' || phase === 'pad_pin') { kp = 5.5; kd = 4.0; }

      let ax = kp * (target.x - p.x) - kd * v.x - windX + dragK * v.x;
      let az = kp * (target.z - p.z) - kd * v.z - windZ + dragK * v.z;
      let ay = 8.0 * (target.y - p.y) - 4.8 * v.y;
      if (phase === 'pad_descend') {
        const desiredVy = clamp(2.5 * (target.y - p.y), -0.45, 1.5);
        ay = 6.0 * (desiredVy - v.y);
      }

      ax = clamp(ax, -6.0, 6.0);
      az = clamp(az, -6.0, 6.0);
      ay = clamp(ay, -5.0, 6.0);

      const totalUp = Math.max(2.0, 9.81 + ay);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = sy * ax + cy * az;

      const desPitch = clamp(Math.atan2(bodyAx, totalUp), -maxTilt, maxTilt);
      const desRoll = clamp(-Math.atan2(bodyAz, totalUp), -maxTilt, maxTilt);

      let cmdRoll = clamp(desRoll - (22 * intRoll + bRoll) / 65, -0.6, 0.6);
      let cmdPitch = clamp(desPitch - (22 * intPitch + bPitch) / 65, -0.6, 0.6);

